INSERT INTO knowledge_documents (title, content, source, category, tags, isActive, createdAt, updatedAt) 
VALUES 
('الفقه الحنفي - شروط صحة الوقف', 'يشترط لصحة الوقف في المذهب الحنفي: التأبيد، والقربة، وخروج الموقوف عن ملك الواقف حكماً، والقبول من الموقوف عليه إن كان معيناً.', 'الفقه الحنفي - كتاب الوقف', 'jurisprudence', 'شروط الوقف، التأبيد، القربة', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الفقه الحنفي - وقف المنقول', 'لا يجوز وقف المنقول في المذهب الحنفي إلا ما جرى به العرف والتعامل كالكتب والسلاح، أو ما كان تابعاً لوقف العقار.', 'الفقه الحنفي - كتاب الوقف', 'jurisprudence', 'وقف المنقول، العرف، التعامل', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الفقه الحنفي - استبدال الوقف', 'لا يجوز استبدال الوقف في المذهب الحنفي إلا إذا تعطلت منافعه بالكلية، وكان في الاستبدال مصلحة ظاهرة، وبإذن القاضي.', 'الفقه الحنفي - كتاب الوقف', 'jurisprudence', 'استبدال الوقف، المصلحة، القاضي', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('أوقاف القدس التاريخية - المسجد الأقصى', 'المسجد الأقصى المبارك وقف إسلامي خالص منذ الفتح الإسلامي، ولا يجوز التصرف فيه أو في أي جزء منه.', 'دراسات تاريخية عن أوقاف القدس', 'historical', 'المسجد الأقصى، القدس، الوقف الإسلامي', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('أوقاف القدس - الأوقاف الصلاحية', 'أوقف صلاح الدين الأيوبي العديد من الأراضي والعقارات في القدس لخدمة المسجد الأقصى والفقراء والمساكين.', 'تاريخ أوقاف القدس', 'historical', 'صلاح الدين، الأوقاف الصلاحية، القدس', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('أوقاف القدس - الزوايا والتكايا', 'انتشرت الزوايا والتكايا الموقوفة في القدس لخدمة الفقراء والمسافرين وطلاب العلم، وكانت تمول من ريع الأوقاف.', 'تاريخ أوقاف القدس', 'historical', 'الزوايا، التكايا، الأوقاف الخيرية', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('أوقاف القدس - المدارس الوقفية', 'أنشئت العديد من المدارس الوقفية في القدس لتعليم القرآن والعلوم الشرعية، وكانت تمول من ريع الأوقاف.', 'تاريخ التعليم في القدس', 'historical', 'المدارس الوقفية، التعليم، القدس', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قانون أملاك الغائبين الإسرائيلي 1950 - التعريف', 'يعرف القانون الإسرائيلي ''الغائب'' بأنه كل من ترك مكان إقامته في فلسطين قبل 1948 أو بعده، وتم الاستيلاء على أملاكه.', 'قانون أملاك الغائبين الإسرائيلي (1950)', 'law', 'أملاك الغائبين، الاستيلاء، فلسطين', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قانون أملاك الغائبين - الأوقاف', 'استولت إسرائيل على العديد من الأوقاف الإسلامية بحجة أنها أملاك غائبين، رغم أن الوقف لا يملكه شخص معين.', 'قانون أملاك الغائبين الإسرائيلي (1950)', 'law', 'الأوقاف، الاستيلاء، أملاك الغائبين', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الانتداب البريطاني - قانون الأوقاف 1922', 'أصدرت سلطات الانتداب البريطاني قانون الأوقاف عام 1922 الذي نظم إدارة الأوقاف وأنشأ المجلس الإسلامي الأعلى.', 'قوانين الانتداب البريطاني', 'historical', 'الانتداب البريطاني، قانون الأوقاف، المجلس الإسلامي', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573));